(150,14,'_elementor_page_settings','a:16:{s:32:\"colors_enable_styleguide_preview\";s:3:\"yes\";s:13:\"system_colors\";a:4:{i:0;a:3:{s:3:\"_id\";s:7:\"primary\";s:5:\"title\";s:9:\"Principal\";s:5:\"color\";s:7:\"#2E8B57\";}i:1;a:3:{s:3:\"_id\";s:9:\"secondary\";s:5:\"title\";s:10:\"Secundario\";s:5:\"color\";s:7:\"#4B0082\";}i:2;a:3:{s:3:\"_id\";s:4:\"text\";s:5:\"title\";s:5:\"Texto\";s:5:\"color\";s:7:\"#7A7A7A\";}i:3;a:3:{s:3:\"_id\";s:6:\"accent\";s:5:\"title\";s:8:\"Ã‰nfasis\";s:5:\"color\";s:7:\"#61CE70\";}}s:13:\"custom_colors\";a:10:{i:0;a:3:{s:3:\"_id\";s:7:\"1f1cf57\";s:5:\"title\";s:8:\"AS-Verde\";s:5:\"color\";s:7:\"#2E8B57\";}i:1;a:3:{s:3:\"_id\";s:7:\"f3d4ae4\";s:5:\"title\";s:9:\"AS-Morado\";s:5:\"color\";s:7:\"#4B0082\";}i:2;a:3:{s:3:\"_id\";s:7:\"c6d3de5\";s:5:\"title\";s:7:\"AS-Rojo\";s:5:\"color\";s:7:\"#C72C48\";}i:3;a:3:{s:3:\"_id\";s:7:\"5d9f9ad\";s:5:\"title\";s:10:\"AS-Naranja\";s:5:\"color\";s:7:\"#D2691E\";}i:4;a:3:{s:3:\"_id\";s:7:\"84e7343\";s:5:\"title\";s:11:\"AS-Amarillo\";s:5:\"color\";s:7:\"#FFD700\";}i:5;a:3:{s:3:\"_id\";s:7:\"7d67754\";s:5:\"title\";s:7:\"AS-Humo\";s:5:\"color\";s:7:\"#FEF6FF\";}i:6;a:3:{s:3:\"_id\";s:7:\"64cef33\";s:5:\"title\";s:14:\"AS-Humo-Oscuro\";s:5:\"color\";s:7:\"#CAC6C3\";}i:7;a:3:{s:3:\"_id\";s:7:\"4bf182a\";s:5:\"title\";s:14:\"AS-Plomo-Claro\";s:5:\"color\";s:7:\"#6B6A61\";}i:8;a:3:{s:3:\"_id\";s:7:\"2432541\";s:5:\"title\";s:8:\"AS-Plomo\";s:5:\"color\";s:7:\"#222222\";}i:9;a:2:{s:3:\"_id\";s:7:\"c60e875\";s:5:\"title\";s:8:\"AS-Negro\";}}s:17:\"system_typography\";a:4:{i:0;a:5:{s:3:\"_id\";s:7:\"primary\";s:5:\"title\";s:9:\"Principal\";s:21:\"typography_typography\";s:6:\"custom\";s:22:\"typography_font_family\";s:17:\"Cinzel Decorative\";s:22:\"typography_font_weight\";s:3:\"600\";}i:1;a:5:{s:3:\"_id\";s:9:\"secondary\";s:5:\"title\";s:10:\"Secundario\";s:21:\"typography_typography\";s:6:\"custom\";s:22:\"typography_font_family\";s:11:\"Roboto Slab\";s:22:\"typography_font_weight\";s:3:\"400\";}i:2;a:5:{s:3:\"_id\";s:4:\"text\";s:5:\"title\";s:5:\"Texto\";s:21:\"typography_typography\";s:6:\"custom\";s:22:\"typography_font_family\";s:4:\"Lora\";s:22:\"typography_font_weight\";s:3:\"400\";}i:3;a:5:{s:3:\"_id\";s:6:\"accent\";s:5:\"title\";s:8:\"Ã‰nfasis\";s:21:\"typography_typography\";s:6:\"custom\";s:22:\"typography_font_family\";s:7:\"Poppins\";s:22:\"typography_font_weight\";s:3:\"500\";}}s:17:\"custom_typography\";a:0:{}s:21:\"default_generic_fonts\";s:10:\"Sans-serif\";s:9:\"site_name\";s:9:\"AndesSuyo\";s:19:\"page_title_selector\";s:14:\"h1.entry-title\";s:15:\"activeItemIndex\";i:1;s:11:\"viewport_md\";i:768;s:11:\"viewport_lg\";i:1025;s:16:\"site_description\";s:21:\"El Origen de lo Bueno\";s:36:\"typography_enable_styleguide_preview\";s:3:\"yes\";s:15:\"container_width\";a:3:{s:4:\"unit\";s:2:\"px\";s:4:\"size\";i:1350;s:5:\"sizes\";a:0:{}}s:25:\"mobile_browser_background\";s:7:\"#FFFEFE\";s:21:\"body_background_color\";s:7:\"#020101\";}'),
